'use strict';
const FontResources=new Map(),FontCatalogue=new Map();
const FREE_FAMILIES=['Noto Sans SC','Noto Serif SC','Noto Sans TC','Noto Serif TC','Noto Sans HK','Noto Sans JP','Noto Serif JP','Noto Sans KR','Noto Serif KR','Ma Shan Zheng','ZCOOL XiaoWei','ZCOOL QingKe HuangYou','ZCOOL KuaiLe','Long Cang','Liu Jian Mao Cao','Zhi Mang Xing','LXGW WenKai TC','LXGW WenKai Mono TC','Roboto','Inter','Open Sans','Lato','Montserrat','Poppins','Source Sans 3','Source Serif 4','Oswald','Raleway','Merriweather','Playfair Display','PT Sans','PT Serif','Nunito','Ubuntu','Fira Sans','Fira Code','JetBrains Mono','Bebas Neue','Anton','Rubik','Work Sans','IBM Plex Sans','IBM Plex Serif','IBM Plex Mono','Libre Baskerville','Libre Franklin','DM Sans','DM Serif Display'];
function norm(s){return s.toLowerCase().replace(/[^a-z0-9]/g,'');}
function fontNames(bytes){try{const v=new DataView(bytes);if(bytes.byteLength<12)return {};const n=v.getUint16(4);let offset=0,length=0,weight=400,weightRange=null;for(let i=0;i<n&&12+i*16+16<=bytes.byteLength;i++){const p=12+i*16;const tag=v.getUint32(p),off=v.getUint32(p+8),len=v.getUint32(p+12);if(off+len>bytes.byteLength)continue;if(tag===0x4f532f32&&len>=6)weight=v.getUint16(off+4);if(tag===0x66766172&&len>=16){const axes=v.getUint16(off+4),count=v.getUint16(off+8),size=v.getUint16(off+10);if(size>=20)for(let a=0;a<count;a++){const q=off+axes+a*size;if(q+20>off+len)break;if(v.getUint32(q)===0x77676874)weightRange=[v.getInt32(q+4)/65536,v.getInt32(q+12)/65536];}}if(tag===0x6e616d65){offset=off;length=len;}}if(!offset||offset+length>bytes.byteLength||length<6)return {};const count=v.getUint16(offset+2),strings=offset+v.getUint16(offset+4),found=new Map();for(let i=0;i<count;i++){const p=offset+6+i*12;if(p+12>offset+length)break;const platform=v.getUint16(p),language=v.getUint16(p+4),id=v.getUint16(p+6),len=v.getUint16(p+8),start=strings+v.getUint16(p+10);if(![1,4,6,16].includes(id)||start+len>offset+length)continue;let text='';if(platform===0||platform===3){for(let k=0;k+1<len;k+=2)text+=String.fromCharCode(v.getUint16(start+k));}else{for(let k=0;k<len;k++)text+=String.fromCharCode(v.getUint8(start+k));}if(!found.has(id)||language===0x409)found.set(id,text);}return {weight,weightRange,family:found.get(16)||found.get(1),postScriptName:found.get(6),fullName:found.get(4)};}catch{return {};}}
async function checkedFetch(url){const response=await fetch(url,{signal:AbortSignal.timeout(60000)});if(!response.ok)throw Error('字体资源下载失败：HTTP '+response.status);return response;}
function renderFontCatalogue(){const list=$('fontnames');list.replaceChildren();const names=new Set(FREE_FAMILIES);for(const record of FontCatalogue.values())names.add(record.family||record.slug);for(const name of [...names].sort()){const o=document.createElement('option');o.value=name;list.append(o);}$('fontcataloguestatus').textContent=`常用免费字体 ${FREE_FAMILIES.length} 系列；已同步目录 ${FontCatalogue.size} 系列。字体文件按选择下载。`;}
async function syncFontCatalogue(){msg('正在读取 Google Fonts 官方仓库目录…');const root=await (await checkedFetch('https://api.github.com/repos/google/fonts/git/trees/main')).json();const branches=root.tree.filter(t=>t.type==='tree'&&['ofl','apache','ufl'].includes(t.path));const results=await Promise.allSettled(branches.map(async b=>({branch:b.path,data:await (await checkedFetch('https://api.github.com/repos/google/fonts/git/trees/'+b.sha)).json()})));let count=0;for(const result of results){if(result.status!=='fulfilled')continue;for(const e of result.value.data.tree||[]){if(e.type!=='tree')continue;FontCatalogue.set(norm(e.path),{slug:e.path,path:result.value.branch+'/'+e.path,family:FREE_FAMILIES.find(f=>norm(f)===norm(e.path))});count++;}}if(!count)throw Error('免费字体目录同步失败，请按名称加载，或导入字体文件');renderFontCatalogue();msg(`已同步 ${count} 个免费字体目录${results.some(r=>r.status==='rejected')?'（部分目录未读取，可重试）':''}。按名称选择后加载，无需 API Key。`);}
async function loadRepositoryFont(record){const metadata=await (await checkedFetch('https://raw.githubusercontent.com/google/fonts/main/'+record.path+'/METADATA.pb')).text(),family=metadata.match(/^name:\s*"([^"]+)"/m)?.[1]||record.family||record.slug;const entries=[...metadata.matchAll(/fonts\s*\{([^}]+)\}/g)].map(m=>({file:m[1].match(/filename:\s*"([^"]+)"/)?.[1],weight:Number(m[1].match(/weight:\s*(\d+)/)?.[1])||400,style:m[1].match(/style:\s*"([^"]+)"/)?.[1]||'normal',ps:m[1].match(/post_script_name:\s*"([^"]+)"/)?.[1]})).filter(e=>e.file&&/\.(ttf|otf)$/.test(e.file)&&e.style==='normal');const chosen=entries.filter(e=>e.file.includes('[')||[400,700].includes(e.weight));if(!chosen.length&&entries.length)chosen.push(entries[0]);if(!chosen.length)throw Error('该字体目录没有支持的 TTF / OTF 文件');const items=[];let meta={family};for(const e of chosen){const url='https://raw.githubusercontent.com/google/fonts/main/'+record.path+'/'+encodeURIComponent(e.file),bytes=await (await checkedFetch(url)).arrayBuffer();if(bytes.byteLength>50*1024*1024)throw Error('单个字体文件超过 50 MB');meta={...meta,...fontNames(bytes)};const face=new FontFace(family,bytes,{weight:meta.weightRange?meta.weightRange.join(' '):String(e.weight)});await face.load();document.fonts.add(face);items.push({bytes,face,weight:e.weight,postScriptName:meta.postScriptName,family:meta.family||family,weightRange:meta.weightRange||null});}addFont(family,family);FontResources.set(family,{...meta,items});record.family=family;renderFontCatalogue();return family;}
async function loadGoogleCSS(family){const url='https://fonts.googleapis.com/css2?family='+encodeURIComponent(family).replace(/%20/g,'+')+'&display=swap',css=await (await checkedFetch(url)).text();const items=[];for(const match of css.matchAll(/@font-face\s*\{([^}]+)\}/g)){const b=match[1],fonturl=b.match(/src:\s*url\(([^)]+)\)/)?.[1]?.replace(/["']/g,''),weight=b.match(/font-weight:\s*([^;]+)/)?.[1]?.trim()||'400',style=b.match(/font-style:\s*([^;]+)/)?.[1]?.trim()||'normal',range=b.match(/unicode-range:\s*([^;]+)/)?.[1]?.trim();if(!fonturl||new URL(fonturl).origin!=='https://fonts.gstatic.com'||style!=='normal')continue;const descriptors={weight,style};if(range)descriptors.unicodeRange=range;const face=new FontFace(family,`url("${fonturl}")`,descriptors);document.fonts.add(face);items.push({face,getBytes:async()=> (await checkedFetch(fonturl)).arrayBuffer()});}if(!items.length)throw Error('未找到该免费字体，请检查名称或同步字体目录');const sample=(S.source?.text||$('text').value||'Aa 字体').replace(/\n/g,' ');try{await document.fonts.load(`24px "${family}"`,sample);}catch{for(const item of items)document.fonts.delete(item.face);throw Error('字体文件加载失败，请检查网络');}addFont(family,family);FontResources.set(family,{family,items});return family;}
async function loadNamedFont(name){name=name.trim();if(!name||name.length>100)throw Error('请输入有效的免费字体名称');if(FontResources.has(name)){msg('字体已加载：'+name);return name;}const record=FontCatalogue.get(norm(name));const family=record?await loadRepositoryFont(record):await loadGoogleCSS(name);msg('已加载免费字体：'+family+'。点击重新匹配比较字形。');return family;}
$('syncfonts').onclick=()=>run(syncFontCatalogue);$('loadnamedfont').onclick=()=>run(()=>loadNamedFont($('fontname').value));$('fontname').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('loadnamedfont').click();}});
$('localfonts').onclick=()=>run(async()=>{if(!window.queryLocalFonts)throw Error('读取本机字体需要桌面 Chrome / Edge 与 HTTPS 或 localhost；也可批量导入字体');const data=await window.queryLocalFonts();let n=0;for(const f of data){const id='Local'+(++S.serial),face=new FontFace(id,`local("${f.postscriptName.replace(/["\\]/g,'')}")`,{weight:String(styleWeight(f.style||f.fullName))});try{await face.load();document.fonts.add(face);addFont(id,f.fullName);FontResources.set(id,{family:f.family,weight:styleWeight(f.style||f.fullName),postScriptName:f.postscriptName,getBytes:async()=> (await f.blob()).arrayBuffer()});n++;}catch{}}msg(`已加载本机 ${n} 个字体。所选字体可随图片送入在线编辑器。`);});
$('fontfile').onchange=()=>{const files=[...$('fontfile').files];$('fontfile').value='';run(async()=>{for(const f of files){if(f.size>50*1024*1024)throw Error('单个字体上限 50 MB');const bytes=await f.arrayBuffer(),id='Import'+(++S.serial),meta=fontNames(bytes),face=new FontFace(id,bytes,{weight:meta.weightRange?meta.weightRange.join(' '):String(meta.weight||400)});await face.load();document.fonts.add(face);addFont(id,meta.fullName||f.name);FontResources.set(id,{...meta,bytes});}msg(`已导入 ${files.length} 个字体，可重新匹配并发送到 Photopea。`);});};
$('onlinefonts').onclick=()=>run(async()=>{for(const [family,slug] of [['Noto Sans SC','notosanssc'],['Noto Serif SC','notoserifsc']])await loadRepositoryFont({family,slug,path:'ofl/'+slug});msg('已加载 Noto Sans SC 与 Noto Serif SC，可重新匹配。');});
renderFontCatalogue();

function styleWeight(style){const s=style.toLowerCase().replace(/[ -]/g,'');if(s.includes('extrabold')||s.includes('ultrabold'))return 800;if(s.includes('semibold')||s.includes('demibold'))return 600;if(s.includes('bold'))return 700;if(s.includes('black')||s.includes('heavy'))return 900;if(s.includes('extralight')||s.includes('ultralight'))return 200;if(s.includes('thin'))return 100;if(s.includes('light'))return 300;if(s.includes('medium'))return 500;return 400;}
function candidateWeights(font){const asset=FontResources.get(font);if(!asset)return [400,700];const items=asset.items||[asset],weights=new Set();for(const item of items){const raw=item.weightRange||item.face?.weight?.split(' ').map(Number);if(raw?.length===2&&raw.every(Number.isFinite)){for(const n of [100,200,300,400,500,600,700,800,900])if(n>=raw[0]&&n<=raw[1])weights.add(n);}else weights.add(item.weight||Number(item.face?.weight)||asset.weight||400);}return [...weights].filter(n=>n>=1&&n<=1000).sort((a,b)=>a-b);}
function fontForWeight(font,weight){const asset=FontResources.get(font);if(!asset)return null;const items=asset.items||[asset];const item=items.find(i=>i.weightRange&&weight>=i.weightRange[0]&&weight<=i.weightRange[1])||items.find(i=>i.weight===weight)||items[0];return {...asset,...item};}
